.bf-btn.primary:hover{background:var(--green);color:#08210f}
/* ══ 本批素材接入（Lovart 玩法入口图标 / UI 元素）══════════════════════════
   ① .gm-ico  侧栏按钮 + 玩法面板标题上的入口图标（默认 display:none，
      img.onload 才显示；onerror 直接摘掉 img → 后面 <span class="gm-emj"> 的 emoji 就是回退文案）
   ② .bf-uiico 结算面板里的 UI 贴图（绿勾/红叉/灯泡），回退方式同上
   ③ 木牌按钮 / 红漆按钮：贴图作 background-image（100% 100% 铺满），
      图片加载失败时 CSS 什么都不做 → 退回原来的描边按钮，布局不变 */
.gm-ico{display:none;width:18px;height:18px;vertical-align:-4px;margin-right:6px;border-radius:4px}
.btn-m .gm-ico{width:14px;height:14px;vertical-align:-2px;margin-right:4px}
.overlay .panel h3 .gm-ico{width:20px;height:20px;vertical-align:-5px}
.bf-uiico{display:none;width:18px;height:18px;vertical-align:-3px;margin-right:5px}
#bfGame .bf-btn.bf-wood{background-color:transparent;background-image:url("art/icons/ui/btn_wood.png");background-size:100% 100%;background-repeat:no-repeat;color:#3a2412;text-shadow:0 1px 0 rgba(255,255,255,.35)}
#bfGame .bf-btn.bf-wood:hover{background-color:transparent;background-image:url("art/icons/ui/btn_wood.png");color:#2a180c;filter:brightness(1.12)}
#bfGame .bf-btn.bf-red{background-color:transparent;background-image:url("art/icons/ui/btn_red.png");background-size:100% 100%;background-repeat:no-repeat;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.55)}
#bfGame .bf-btn.bf-red:hover{background-color:transparent;background-image:url("art/icons/ui/btn_red.png");color:#fff;filter:brightness(1.1)}
